import test, { type TestContext } from 'node:test';
import assert from 'node:assert/strict';
import { createServer, type RequestListener } from 'node:http';
import { once } from 'node:events';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { JiraClient } from '../src/jira/client.js';
import { loadConfig } from '../src/config.js';
import { loadDataset, saveDataset, saveFile } from '../src/storage.js';
import { calculate } from '../src/analytics/calculate.js';
import { renderReport } from '../src/report/render.js';
import { config, rawIssue } from './fixtures.js';

async function serverFor(t: TestContext, handler: RequestListener): Promise<string> {
  const server = createServer(handler);
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  t.after(() => new Promise<void>((resolve, reject) => {
    server.closeAllConnections();
    server.close(error => error ? reject(error) : resolve());
  }));
  const address = server.address();
  if (!address || typeof address === 'string') throw new Error('Нет порта тестового сервера');
  return `http://127.0.0.1:${address.port}`;
}

test('HTTP → пагинация → JSON на диске → аналитика → HTML', async t => {
  const starts: number[] = [];
  const baseUrl = await serverFor(t, (request, response) => {
    const url = new URL(request.url!, 'http://localhost');
    assert.equal(url.pathname, '/rest/api/2/search');
    assert.equal(url.searchParams.get('expand'), 'changelog');
    assert.equal(request.headers.authorization, undefined);
    assert.match(url.searchParams.get('jql')!, /project = "TEST"/);
    const startAt = Number(url.searchParams.get('startAt'));
    starts.push(startAt);
    // Сервер может ограничить страницу сильнее запрошенного pageSize.
    response.setHeader('Content-Type', 'application/json');
    response.end(JSON.stringify({ startAt, total: 3, issues: [rawIssue(`TEST-${startAt + 1}`)] }));
  });
  const directory = await mkdtemp(join(tmpdir(), 'jira-integration-'));
  t.after(() => rm(directory, { recursive: true, force: true }));
  const dataset = await new JiraClient({ ...config, baseUrl }, '').fetchProject();
  assert.deepEqual(starts, [0, 1, 2]);
  assert.equal(dataset.complete, true);
  const path = join(directory, 'issues.json');
  await saveDataset(path, dataset);
  const loaded = await loadDataset(path);
  const metrics = calculate(loaded.issues, ['Closed'], 5);
  assert.equal(metrics.closedCount, 3);
  assert.equal(metrics.daily.at(-1)!.closedTotal, 3);
  await saveFile(join(directory, 'index.html'), renderReport(loaded, metrics, ['Closed']));
  assert.ok((await readFile(join(directory, 'index.html'), 'utf8')).includes('<svg'));
});

test('maxIssues помечает отчёт как неполный', async t => {
  const baseUrl = await serverFor(t, (_request, response) => {
    response.end(JSON.stringify({ startAt: 0, total: 20, issues: [rawIssue()] }));
  });
  const dataset = await new JiraClient({ ...config, baseUrl, maxIssues: 1 }, '').fetchProject();
  assert.equal(dataset.complete, false);
  assert.equal(dataset.issues.length, 1);
});

test('429 повторяется с ограничением числа попыток', async t => {
  let attempts = 0;
  const baseUrl = await serverFor(t, (_request, response) => {
    attempts++;
    response.statusCode = attempts === 1 ? 429 : 200;
    response.setHeader('Retry-After', '0');
    response.end(JSON.stringify({ startAt: 0, total: 0, issues: [] }));
  });
  const dataset = await new JiraClient({ ...config, baseUrl, retries: 1 }, '').fetchProject();
  assert.equal(attempts, 2);
  assert.equal(dataset.complete, true);
});

test('401 не повторяется и объясняет проблему авторизации', async t => {
  let attempts = 0;
  const baseUrl = await serverFor(t, (_request, response) => {
    attempts++;
    response.writeHead(401).end();
  });
  await assert.rejects(new JiraClient({ ...config, baseUrl, retries: 3 }, '').fetchProject(), /анонимный доступ запрещён/);
  assert.equal(attempts, 1);
});

test('зависший HTTP-запрос прерывается по таймауту', async t => {
  const baseUrl = await serverFor(t, () => {});
  await assert.rejects(new JiraClient({ ...config, baseUrl, timeoutMs: 40 }, '').fetchProject(), /timeout/i);
});

test('пустая страница до конца списка обнаруживается', async t => {
  const baseUrl = await serverFor(t, (_request, response) => {
    response.end(JSON.stringify({ startAt: 0, total: 10, issues: [] }));
  });
  await assert.rejects(new JiraClient({ ...config, baseUrl }, '').fetchProject(), /пустую страницу/);
});

test('конфигурация валидируется до обращения к API', async t => {
  const directory = await mkdtemp(join(tmpdir(), 'jira-config-'));
  t.after(() => rm(directory, { recursive: true, force: true }));
  const path = join(directory, 'config.json');
  await saveFile(path, JSON.stringify({ ...config, project: 'HDFS OR project = OTHER' }));
  await assert.rejects(loadConfig(path), /ключ проекта/);
  await saveFile(path, JSON.stringify({ ...config, pageSize: 0 }));
  await assert.rejects(loadConfig(path), /pageSize/);
});

import { setTimeout as sleep } from 'node:timers/promises';
import type { Config } from '../config.js';
import { log } from '../logger.js';
import { object, nonnegative, type Dataset, type Issue } from '../model.js';
import { normalizeIssue } from './normalize.js';

class HttpError extends Error {
  constructor(readonly status: number, readonly retryAfterMs: number) {
    super(status === 401 || status === 403
      ? `JIRA HTTP ${status}: анонимный доступ запрещён. Проверьте права проекта; при необходимости задайте JIRA_TOKEN.`
      : `JIRA HTTP ${status}`);
  }
}

/** REST-клиент Apache Jira Server/Data Center API v2. */
export class JiraClient {
  constructor(private readonly config: Config, private readonly token = process.env.JIRA_TOKEN) {
    if (token && !config.baseUrl.startsWith('https://')) throw new Error('Токен разрешён только для HTTPS');
  }

  /** Делает GET с таймаутом и ограниченными повторами сетевых ошибок, 429 и 5xx. */
  async get(path: string, parameters: Record<string, string>): Promise<unknown> {
    const url = new URL(`${this.config.baseUrl}/rest/api/2/${path}`);
    url.search = new URLSearchParams(parameters).toString();
    for (let attempt = 0; ; attempt++) {
      const startedAt = Date.now();
      log(`GET ${url.toString()} — попытка ${attempt + 1}`);
      try {
        const response = await fetch(url, {
          headers: { Accept: 'application/json', ...(this.token ? { Authorization: `Bearer ${this.token}` } : {}) },
          signal: AbortSignal.timeout(this.config.timeoutMs),
          redirect: 'error',
        });
        log(`HTTP ${response.status} — ${Date.now() - startedAt} мс — ${url.pathname}`, response.ok ? 'INFO' : 'WARN');
        if (!response.ok) {
          const retryAfter = response.headers.get('retry-after');
          const delay = retryAfter == null ? 0 : /^\d+$/.test(retryAfter)
            ? Number(retryAfter) * 1000 : Math.max(0, Date.parse(retryAfter) - Date.now());
          await response.body?.cancel();
          throw new HttpError(response.status, Number.isFinite(delay) ? delay : 0);
        }
        return await response.json();
      } catch (error) {
        const retryable = error instanceof HttpError ? error.status === 429 || error.status >= 500
          : error instanceof TypeError || (error instanceof Error && ['TimeoutError', 'AbortError'].includes(error.name));
        if (!retryable || attempt >= this.config.retries) {
          log(`Запрос завершился ошибкой: ${error instanceof Error ? error.message : String(error)}`, 'ERROR');
          throw error;
        }
        const delay = Math.max(500 * 2 ** attempt, error instanceof HttpError ? error.retryAfterMs : 0);
        // Не повторяем запрос раньше Retry-After; долгую паузу оставляем пользователю.
        if (delay > 60_000) throw new Error(`JIRA просит повторить запрос через ${Math.ceil(delay / 1000)} с. Запустите загрузку позже.`);
        log(`Повтор запроса ${attempt + 1}/${this.config.retries} через ${delay} мс: ${error instanceof Error ? error.message : String(error)}`, 'WARN');
        await sleep(delay);
      }
    }
  }

  /** Загружает все страницы или maxIssues задач; 0 означает весь проект. */
  async fetchProject(): Promise<Dataset> {
    const jql = `project = "${this.config.project}" ORDER BY created DESC, key DESC`;
    const issues: Issue[] = [];
    const seen = new Set<string>();
    let startAt = 0;
    let total: number | undefined;
    while (total === undefined || startAt < total) {
      const remaining = this.config.maxIssues === 0 ? Infinity : this.config.maxIssues - issues.length;
      if (remaining <= 0) break;
      const page = object(await this.get('search', {
        jql, startAt: String(startAt), maxResults: String(Math.min(this.config.pageSize, remaining)),
        fields: 'created,resolutiondate,status,priority,timespent,assignee,reporter', expand: 'changelog',
      }), 'JIRA search');
      const pageTotal = nonnegative(page.total, 'search.total');
      if (!Number.isInteger(pageTotal) || page.startAt !== startAt || !Array.isArray(page.issues)) {
        throw new Error('Некорректная страница JIRA');
      }
      if (total !== undefined && total !== pageTotal) throw new Error('Число задач изменилось во время загрузки. Повторите выгрузку.');
      total = pageTotal;
      if (!page.issues.length && startAt < total) throw new Error('JIRA вернула пустую страницу до конца списка');
      for (const raw of page.issues) {
        const issue = normalizeIssue(raw);
        if (seen.has(issue.key)) throw new Error(`Повтор задачи ${issue.key}: список изменился во время загрузки`);
        seen.add(issue.key);
        issues.push(issue);
      }
      startAt += page.issues.length;
      log(`Получено задач: ${issues.length} / ${total}`);
      if (startAt < total && (this.config.maxIssues === 0 || issues.length < this.config.maxIssues)) {
        await sleep(this.config.requestDelayMs);
      }
    }
    return {
      version: 1, source: this.config.baseUrl, project: this.config.project,
      fetchedAt: new Date().toISOString(), jql, total: total ?? 0,
      complete: issues.length === total, issues,
    };
  }
}

import { appendFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

let logFile: string | undefined;
type LogLevel = 'INFO' | 'WARN' | 'ERROR';

/** Создаёт файл логов; существующие записи сохраняются между запусками. */
export function initializeLogger(path: string): void {
  mkdirSync(dirname(path), { recursive: true });
  appendFileSync(path, '', 'utf8');
  logFile = path;
}

/** Пишет событие с UTC-временем и уровнем в stderr и настроенный файл. */
export function log(message: string, level: LogLevel = 'INFO'): void {
  const line = `[${new Date().toISOString()}] [${level}] ${message.replace(/[\r\n]+/g, ' ')}`;
  console.error(line);
  // Синхронная запись гарантирует сохранение последней ошибки перед выходом CLI.
  if (logFile) appendFileSync(logFile, `${line}\n`, 'utf8');
}

/** Минимальная модель: сохраняем только данные, необходимые для отчёта. */
export interface User {
  id: string;
  name: string;
}

export interface StatusChange {
  at: string;
  from: string;
  to: string;
}

export interface Issue {
  key: string;
  created: string;
  resolved: string | null;
  status: string;
  priority: string;
  assignee: User | null;
  reporter: User | null;
  loggedSeconds: number | null;
  changes: StatusChange[];
}

export interface Dataset {
  version: 1;
  source: string;
  project: string;
  fetchedAt: string;
  jql: string;
  total: number;
  complete: boolean;
  issues: Issue[];
}

/** Проверяет структуру JSON до доступа к его полям. */
export function object(value: unknown, label: string): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error(`${label}: ожидался объект`);
  }
  return value as Record<string, unknown>;
}

/** Проверяет строковое поле ответа или сохранённых данных. */
export function string(value: unknown, label: string): string {
  if (typeof value !== 'string' || !value.trim()) throw new Error(`${label}: ожидалась непустая строка`);
  return value;
}

/** Проверяет дату, возвращая нормализованную UTC-строку. */
export function timestamp(value: unknown, label: string): string {
  const text = string(value, label);
  const millis = Date.parse(text);
  if (!Number.isFinite(millis)) throw new Error(`${label}: некорректная дата`);
  return new Date(millis).toISOString();
}

/** Проверяет неотрицательное числовое значение. */
export function nonnegative(value: unknown, label: string): number {
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
    throw new Error(`${label}: ожидалось неотрицательное число`);
  }
  return value;
}

import { object, string, timestamp, nonnegative, type Issue, type StatusChange, type User } from '../model.js';

function user(value: unknown): User | null {
  if (value == null) return null;
  const raw = object(value, 'Пользователь');
  return {
    id: string(raw.key ?? raw.accountId ?? raw.name, 'ID пользователя'),
    name: string(raw.displayName ?? raw.name, 'Имя пользователя'),
  };
}

/** Преобразует ответ Jira Server/Data Center; неполную историю не принимает. */
export function normalizeIssue(value: unknown): Issue {
  const raw = object(value, 'Задача');
  const key = string(raw.key, 'key');
  const fields = object(raw.fields, `${key}.fields`);
  const changelog = object(raw.changelog, `${key}.changelog`);
  if (!Array.isArray(changelog.histories) || changelog.startAt !== 0 ||
      changelog.total !== changelog.histories.length) {
    throw new Error(`${key}: история изменений неполная; расчёт времени по статусам остановлен`);
  }
  const changes: StatusChange[] = [];
  for (const value of changelog.histories) {
    const history = object(value, `${key}.history`);
    if (!Array.isArray(history.items)) throw new Error(`${key}: отсутствуют элементы истории`);
    for (const value of history.items) {
      const item = object(value, `${key}.history.item`);
      if (item.field === 'status') {
        changes.push({
          at: timestamp(history.created, `${key}.history.created`),
          from: string(item.fromString, `${key}.fromString`),
          to: string(item.toString, `${key}.toString`),
        });
      }
    }
  }
  return {
    key,
    created: timestamp(fields.created, `${key}.created`),
    resolved: fields.resolutiondate == null ? null : timestamp(fields.resolutiondate, `${key}.resolutiondate`),
    status: string(object(fields.status, `${key}.status`).name, `${key}.status.name`),
    priority: fields.priority == null ? 'Не указана' : string(object(fields.priority, 'priority').name, 'priority.name'),
    assignee: user(fields.assignee), reporter: user(fields.reporter),
    loggedSeconds: fields.timespent == null ? null : nonnegative(fields.timespent, `${key}.timespent`),
    changes: changes.sort((a, b) => a.at.localeCompare(b.at)),
  };
}

import { readFile } from 'node:fs/promises';
import { object, string } from './model.js';

export interface Config {
  baseUrl: string;
  project: string;
  /** Настраивается в config/default.json: для строго Closed задайте "closedStatuses": ["Closed"] и "maxIssues": 0 для загрузки всего проекта. */
  closedStatuses: string[];
  pageSize: number;
  maxIssues: number;
  timeoutMs: number;
  retries: number;
  requestDelayMs: number;
  histogramBins: number;
  dataFile: string;
  reportFile: string;
  logFile: string;
}

/** Загружает настройки. Пути к данным считаются от рабочей директории. */
export async function loadConfig(path: string): Promise<Config> {
  const raw = object(JSON.parse(await readFile(path, 'utf8')), 'Конфигурация');
  const url = new URL(string(raw.baseUrl, 'baseUrl'));
  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.search || url.hash) {
    throw new Error('baseUrl должен быть HTTP(S) URL без пароля, query и fragment');
  }
  const project = string(raw.project, 'project');
  if (!/^[A-Z][A-Z0-9_]*$/.test(project)) throw new Error('Некорректный ключ проекта');
  if (!Array.isArray(raw.closedStatuses) || !raw.closedStatuses.length) {
    throw new Error('closedStatuses должен содержать хотя бы один статус');
  }
  const integer = (key: string, min: number, max: number): number => {
    const value = raw[key];
    if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
      throw new Error(`${key}: ожидалось целое число от ${min} до ${max}`);
    }
    return value;
  };
  return {
    baseUrl: url.toString().replace(/\/$/, ''), project,
    closedStatuses: raw.closedStatuses.map(value => string(value, 'closedStatuses')),
    pageSize: integer('pageSize', 1, 1000),
    maxIssues: integer('maxIssues', 0, 1_000_000),
    timeoutMs: integer('timeoutMs', 1, 300_000),
    retries: integer('retries', 0, 10),
    requestDelayMs: integer('requestDelayMs', 0, 60_000),
    histogramBins: integer('histogramBins', 1, 100),
    dataFile: string(raw.dataFile, 'dataFile'),
    reportFile: string(raw.reportFile, 'reportFile'),
    logFile: string(raw.logFile ?? 'logs/jira-analytics.log', 'logFile'),
  };
}

import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';
import { object, string, timestamp, nonnegative, type Dataset, type Issue, type User } from './model.js';

/** Записывает файл через временный, чтобы ошибка не испортила предыдущий результат. */
export async function saveFile(path: string, contents: string): Promise<void> {
  await mkdir(dirname(path), { recursive: true });
  const temporary = `${path}.${process.pid}.tmp`;
  await writeFile(temporary, contents, 'utf8');
  await rename(temporary, path);
}

/** Сохраняет нормализованный снимок для повторяемых расчётов без сети. */
export async function saveDataset(path: string, dataset: Dataset): Promise<void> {
  await saveFile(path, JSON.stringify(dataset, null, 2));
}

/** Загружает и проверяет локальный снимок; повреждённые данные не пропускает. */
export async function loadDataset(path: string): Promise<Dataset> {
  return parseDataset(JSON.parse(await readFile(path, 'utf8')));
}

/** Проверяет версию, метаданные и обязательные поля сохранённого снимка. */
export function parseDataset(value: unknown): Dataset {
  const raw = object(value, 'Снимок');
  if (raw.version !== 1 || !Array.isArray(raw.issues) || typeof raw.complete !== 'boolean') {
    throw new Error('Неподдерживаемый формат снимка');
  }
  const parseUser = (value: unknown): User | null => {
    if (value === null) return null;
    const raw = object(value, 'user');
    return { id: string(raw.id, 'user.id'), name: string(raw.name, 'user.name') };
  };
  const issues: Issue[] = raw.issues.map(value => {
    const issue = object(value, 'issue');
    if (!Array.isArray(issue.changes)) throw new Error('Отсутствует история статусов');
    return {
      key: string(issue.key, 'key'), created: timestamp(issue.created, 'created'),
      resolved: issue.resolved === null ? null : timestamp(issue.resolved, 'resolved'),
      status: string(issue.status, 'status'), priority: string(issue.priority, 'priority'),
      assignee: parseUser(issue.assignee), reporter: parseUser(issue.reporter),
      loggedSeconds: issue.loggedSeconds === null ? null : nonnegative(issue.loggedSeconds, 'loggedSeconds'),
      changes: issue.changes.map(value => {
        const change = object(value, 'change');
        return { at: timestamp(change.at, 'change.at'), from: string(change.from, 'change.from'), to: string(change.to, 'change.to') };
      }).sort((a, b) => a.at.localeCompare(b.at)),
    };
  });
  const total = nonnegative(raw.total, 'total');
  if (!Number.isInteger(total) || total < issues.length || raw.complete !== (total === issues.length) ||
      new Set(issues.map(issue => issue.key)).size !== issues.length) {
    throw new Error('Снимок содержит дубликаты или противоречивые счётчики');
  }
  return {
    version: 1, source: string(raw.source, 'source'), project: string(raw.project, 'project'),
    fetchedAt: timestamp(raw.fetchedAt, 'fetchedAt'), jql: string(raw.jql, 'jql'),
    total, complete: raw.complete, issues,
  };
}

import type { Issue, User } from '../model.js';
import { histogram } from './histogram.js';

const HOUR_MS = 3_600_000;
const DAY_MS = 24 * HOUR_MS;

/** Находит последнее вхождение в группу закрытых статусов для сейчас закрытой задачи. */
export function closureTime(issue: Issue, closedStatuses: string[]): { at: number; fallback: boolean } | null {
  const closed = new Set(closedStatuses);
  if (!closed.has(issue.status)) return null;
  const transition = issue.changes.filter(change => !closed.has(change.from) && closed.has(change.to)).at(-1);
  if (transition) return { at: Date.parse(transition.at), fallback: false };
  if (issue.resolved) return { at: Date.parse(issue.resolved), fallback: true };
  return null;
}

/** Суммирует повторные посещения каждого статуса до последнего закрытия, в часах. */
export function timeByStatus(issue: Issue, closedAt: number): Map<string, number> {
  const result = new Map<string, number>();
  let cursor = Date.parse(issue.created);
  let status = issue.changes[0]?.from ?? issue.status;
  if (closedAt < cursor) throw new Error(`${issue.key}: закрытие раньше создания`);
  const add = (until: number) => result.set(status, (result.get(status) ?? 0) + (until - cursor) / HOUR_MS);
  for (const change of issue.changes) {
    const at = Date.parse(change.at);
    if (at < cursor || change.from !== status) throw new Error(`${issue.key}: несогласованная история статусов`);
    if (at > closedAt) break;
    add(at);
    cursor = at;
    status = change.to;
  }
  if (cursor < closedAt) add(closedAt);
  return result;
}

export interface DailyCount { day: string; created: number; closed: number; createdTotal: number; closedTotal: number }
export interface UserCount { id: string; name: string; assigned: number; reported: number; total: number }

/** Считает уникальные задачи пользователя, сохраняя отдельные счётчики ролей. */
export function topUsers(issues: Issue[], limit = 30): UserCount[] {
  const users = new Map<string, UserCount>();
  const get = (user: User): UserCount => {
    let entry = users.get(user.id);
    if (!entry) {
      entry = { ...user, assigned: 0, reported: 0, total: 0 };
      users.set(user.id, entry);
    }
    return entry;
  };
  for (const issue of issues) {
    if (issue.assignee) get(issue.assignee).assigned++;
    if (issue.reporter) get(issue.reporter).reported++;
    for (const id of new Set([issue.assignee?.id, issue.reporter?.id])) {
      if (id) users.get(id)!.total++;
    }
  }
  return [...users.values()].sort((a, b) => b.total - a.total || a.id.localeCompare(b.id)).slice(0, limit);
}

/** Строит шесть наборов метрик; календарные дни считаются в UTC. */
export function calculate(issues: Issue[], closedStatuses: string[], binCount: number) {
  const lifetimes: number[] = [];
  const loggedHours: number[] = [];
  const statuses = new Map<string, number[]>();
  const priorities = new Map<string, number>();
  const events = new Map<string, { created: number; closed: number }>();
  const warnings: string[] = [];
  let closedCount = 0;
  let missingWorklogs = 0;
  const event = (at: number) => {
    const day = new Date(at).toISOString().slice(0, 10);
    if (!events.has(day)) events.set(day, { created: 0, closed: 0 });
    return events.get(day)!;
  };
  for (const issue of issues) {
    event(Date.parse(issue.created)).created++;
    priorities.set(issue.priority, (priorities.get(issue.priority) ?? 0) + 1);
    if (!closedStatuses.includes(issue.status)) continue;
    closedCount++;
    if (issue.loggedSeconds === null) missingWorklogs++;
    else loggedHours.push(issue.loggedSeconds / 3600);
    const closure = closureTime(issue, closedStatuses);
    if (!closure) {
      warnings.push(`${issue.key}: нет даты закрытия, исключена из временных графиков`);
      continue;
    }
    const lifetime = (closure.at - Date.parse(issue.created)) / HOUR_MS;
    if (lifetime < 0) throw new Error(`${issue.key}: закрытие раньше создания`);
    lifetimes.push(lifetime);
    event(closure.at).closed++;
    if (closure.fallback) {
      warnings.push(`${issue.key}: дата закрытия взята из resolutiondate; нет перехода в закрытый статус. Время по статусам не рассчитывается.`);
      continue;
    }
    for (const [status, hours] of timeByStatus(issue, closure.at)) {
      if (!statuses.has(status)) statuses.set(status, []);
      statuses.get(status)!.push(hours);
    }
  }
  const days = [...events.keys()].sort();
  const daily: DailyCount[] = [];
  let createdTotal = 0;
  let closedTotal = 0;
  if (days.length) {
    const end = Date.parse(days.at(-1)!);
    for (let date = Date.parse(days[0]!); date <= end; date += DAY_MS) {
      const day = new Date(date).toISOString().slice(0, 10);
      const counts = events.get(day) ?? { created: 0, closed: 0 };
      createdTotal += counts.created;
      closedTotal += counts.closed;
      daily.push({ day, ...counts, createdTotal, closedTotal });
    }
  }
  return {
    issueCount: issues.length, closedCount, missingWorklogs, warnings,
    lifetime: histogram(lifetimes, binCount),
    statuses: [...statuses].sort(([a], [b]) => a.localeCompare(b)).map(([status, values]) => ({ status, histogram: histogram(values, binCount) })),
    daily, users: topUsers(issues), worklogs: histogram(loggedHours, binCount),
    priorities: [...priorities].sort((a, b) => b[1] - a[1]).map(([priority, count]) => ({ priority, count })),
  };
}

export type Analytics = ReturnType<typeof calculate>;

export interface Bin { from: number; to: number; count: number }

const TIME_UNITS = [
  { hours: 1 / 3600, label: 'секунды', short: 'с', note: '' },
  { hours: 1 / 60, label: 'минуты', short: 'мин', note: '' },
  { hours: 1, label: 'часы', short: 'ч', note: '' },
  { hours: 24, label: 'дни', short: 'дн.', note: '1 день = 24 часа.' },
  { hours: 24 * 30, label: 'месяцы', short: 'мес.', note: 'Для шкалы 1 месяц = 30 дней.' },
  { hours: 24 * 365, label: 'годы', short: 'г.', note: 'Для шкалы 1 год = 365 дней.' },
] as const;

/** Выбирает единицу времени так, чтобы один шаг не был дробью крупной единицы. */
export function durationUnit(stepHours: number) {
  return TIME_UNITS.filter(unit => stepHours >= unit.hours).at(-1) ?? TIME_UNITS[0];
}

/** Округляет шаг вверх до удобного значения: 1, 2, 2.5, 5, 10 × степень десяти. */
export function niceStep(value: number): number {
  const magnitude = 10 ** Math.floor(Math.log10(value));
  const factor = [1, 2, 2.5, 5, 10].find(candidate => candidate * magnitude >= value)!;
  return factor * magnitude;
}

function timeStep(rawHours: number): number {
  let unit = durationUnit(rawHours);
  let step = niceStep(rawHours / unit.hours) * unit.hours;
  // Если округление пересекло границу единиц, округляем уже в новой единице:
  // например, 23 часа превращаются в 1 день, а не в 25 часов.
  while (durationUnit(step) !== unit) {
    unit = durationUnit(step);
    step = niceStep(rawHours / unit.hours) * unit.hours;
  }
  return step;
}

/** Равные округлённые интервалы времени в часах; binCount — желаемый максимум их числа. */
export function histogram(values: number[], binCount: number): Bin[] {
  if (!Number.isInteger(binCount) || binCount < 1) throw new Error('Число интервалов должно быть положительным целым');
  if (values.some(value => !Number.isFinite(value) || value < 0)) throw new Error('Недопустимое значение гистограммы');
  if (!values.length) return [];
  const maximum = values.reduce((max, value) => Math.max(max, value), 0);
  const width = maximum === 0 ? 1 : timeStep(maximum / binCount);
  const count = maximum === 0 ? 1 : Math.ceil(maximum / width);
  const bins = Array.from({ length: count }, (_, i) => ({ from: i * width, to: (i + 1) * width, count: 0 }));
  for (const value of values) bins[Math.min(bins.length - 1, Math.floor(value / width))]!.count++;
  return bins;
}

